func printTrailThreadDetail(w io.Writer, out api.TrailThreadDetailResponse, jsonOut bool) error {
	if jsonOut {
		enc := json.NewEncoder(w)
		enc.SetIndent("", "  ")
		if err := enc.Encode(out); err != nil {
			return fmt.Errorf("encode thread JSON: %w", err)
		}
		return nil
	}
	t := out.Thread
	marker := "unresolved"
	if t.Resolved {
		marker = "resolved"
	}
	fmt.Fprintf(w, "Thread %s [%s]: %s\n\n", t.ID, marker, t.Title)
	for _, m := range out.Messages {
		fmt.Fprintf(w, "%s  %s\n%s\n", m.Author, m.CreatedAt.Format(time.RFC3339), m.Body)
		for _, r := range m.Replies {
			fmt.Fprintf(w, "  ↳ %s  %s\n  %s\n", r.Author, r.CreatedAt.Format(time.RFC3339), r.Body)
		}
		fmt.Fprintln(w)
	}
	return nil
}

