41	// withNumberedTrail resolves a numbered trail (by --trail selector or current
42	// branch / --branch) and invokes fn inside an authenticated API context. It
43	// centralizes the resolution boilerplate for the comment subtree.
44	func withNumberedTrail(cmd *cobra.Command, fn func(ctx context.Context, client *api.Client, found *api.TrailResource, forge, owner, repo string) error) error {
45		repoOverride := trailRepoFlag(cmd)
46		selector := trailSubcommandSelector(cmd)
47		branch := trailBranchFlag(cmd)
48		if selector != "" && strings.TrimSpace(branch) != "" {
